import { createContext, useState } from 'react';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [feedbackData, setFeedbackData] = useState({
    sections: [
      { id: 1, name: 'Course Content', questions: [] },
      { id: 2, name: 'Teaching Style', questions: [] },
      { id: 3, name: 'Classroom Environment', questions: [] },
    ],
    questions: [],
  });

  const addSection = (sectionName) => {
    setFeedbackData((prevFeedbackData) => {
      const newSection = {
        id: prevFeedbackData.sections.length + 1,
        name: sectionName,
        questions: [],
      };
      return { ...prevFeedbackData, sections: [...prevFeedbackData.sections, newSection] };
    });
  };

  const addQuestion = (sectionId, questionText) => {
    setFeedbackData((prevFeedbackData) => {
      const sectionIndex = prevFeedbackData.sections.findIndex((section) => section.id === sectionId);
      if (sectionIndex >= 0) {
        const newQuestion = {
          id: prevFeedbackData.questions.length + 1,
          text: questionText,
        };
        prevFeedbackData.sections[sectionIndex].questions = [...prevFeedbackData.sections[sectionIndex].questions, newQuestion];
        return { ...prevFeedbackData };
      }
      return prevFeedbackData;
    });
  };

  const getFeedbackData = () => feedbackData;

  return (
    <FeedbackContext.Provider value={{ feedbackData, addSection, addQuestion, getFeedbackData }}>
      {children}
    </FeedbackContext.Provider>
  );
};

export { FeedbackContext, FeedbackProvider };
