var ctx = canvas.getContext('2d');
var w = canvas.width;
var h = canvas.height;

// Define the constants
var G = 9.81; // acceleration due to gravity
var l = 200; // length of the pendulum
var m = 1; // mass of the pendulum bob
var A0 = 30; // initial angle in degrees

// Initialize the angle and acceleration arrays
var theta = [];
var dtheta = [];

// Function to calculate the pendulum's angle and acceleration
function update() {
  for (var i = theta.length - 1; i > 0; i--) {
    theta[i] = theta[i - 1];
    dtheta[i] = dtheta[i - 1];
  }
  var dtheta0 = (A0 * Math.PI / 180) / l;
  dtheta[0] = -dtheta0 * G / Math.sin(theta[0]);
  theta[0] = theta[0] + dtheta[0];

  // Draw the pendulum
  ctx.clearRect(0, 0, w, h);
  ctx.beginPath();
  ctx.moveTo(w / 2, h - l);
  ctx.lineTo(w / 2 + l * Math.sin(theta[0]), h - l * Math.cos(theta[0]));
  ctx.strokeStyle = 'black';
  ctx.stroke();
}

// Function to update the pendulum at each frame
function animate() {
  requestAnimationFrame(animate);
  update();
}

